<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { eliminarComponente, guardarComponente, listarComponentes, type CatalogoComponente, type ComponenteOperacional, type ComponentePayload, type SistemaComponente, type TipoComponenteCatalogo } from '../services/componentes'
const records=ref<ComponenteOperacional[]>([]),types=ref<TipoComponenteCatalogo[]>([]),systems=ref<SistemaComponente[]>([]),variables=ref<CatalogoComponente[]>([]),conditions=ref<Record<string,string>>({}),query=ref(''),systemFilter=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0)
const form=reactive<ComponentePayload>({nombre:'',observacion:'',tipo_componente_id:null,sistema_id:[],puntos:[{latitud:null,longitud:null}],control_calidad:false,variable_sunass:'',cod_sunass:'',caudal:null,capacidad_nominal:null,volumen:null,fecha_instalacion:'',ultimo_mantenimiento:'',frecuencia_mant_meses:null,condicion:''})
const selectedType=computed(()=>types.value.find(x=>x.id===form.tipo_componente_id))
async function load(target=1){loading.value=true;error.value='';try{const r=await listarComponentes(query.value,systemFilter.value,target);records.value=r.data;types.value=r.tipos;systems.value=r.sistemas;variables.value=r.variables_sunass;conditions.value=r.condiciones;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function resetPoints(){const count=selectedType.value?.puntos||1;form.puntos=Array.from({length:count},()=>({latitud:null,longitud:null}))}
function open(item?:ComponenteOperacional){editing.value=item?.id??null;Object.assign(form,item?{nombre:item.nombre,observacion:item.observacion,tipo_componente_id:item.tipo_componente_id,sistema_id:item.sistemas.map(x=>x.id),puntos:item.puntos.map(x=>({...x})),control_calidad:item.control_calidad,variable_sunass:item.variable_sunass||'',cod_sunass:item.cod_sunass||'',caudal:item.caudal,capacidad_nominal:item.capacidad_nominal,volumen:item.volumen,fecha_instalacion:item.fecha_instalacion,ultimo_mantenimiento:item.ultimo_mantenimiento,frecuencia_mant_meses:item.frecuencia_mant_meses,condicion:item.condicion}:{nombre:'',observacion:'',tipo_componente_id:types.value[0]?.id??null,sistema_id:[],puntos:[{latitud:null,longitud:null}],control_calidad:false,variable_sunass:'',cod_sunass:'',caudal:null,capacidad_nominal:null,volumen:null,fecha_instalacion:'',ultimo_mantenimiento:'',frecuencia_mant_meses:null,condicion:Object.keys(conditions.value)[0]||''});if(!item)resetPoints();modal.value=true}
function validate(){if(!form.nombre.trim()||!form.observacion.trim()||!form.tipo_componente_id||!form.sistema_id.length)return'Complete la información básica y seleccione al menos un sistema.';if(form.puntos.some(x=>x.latitud==null||x.longitud==null))return'Complete todas las coordenadas requeridas.';if([form.caudal,form.capacidad_nominal,form.volumen,form.frecuencia_mant_meses].some(x=>x==null)||!form.fecha_instalacion||!form.ultimo_mantenimiento||!form.condicion)return'Complete la información técnica y de mantenimiento.';if(form.control_calidad&&(!form.variable_sunass||!form.cod_sunass.trim()))return'Complete la variable y el código SUNASS.';return''}
async function save(){const validation=validate();if(validation){error.value=validation;return}saving.value=true;error.value='';try{await guardarComponente({...form,nombre:form.nombre.trim(),observacion:form.observacion.trim(),variable_sunass:form.control_calidad?form.variable_sunass:'',cod_sunass:form.control_calidad?form.cod_sunass.trim():''},editing.value??undefined);modal.value=false;success.value=`Componente ${editing.value?'actualizado':'registrado'} correctamente.`;await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:ComponenteOperacional){if(!confirm(`¿Eliminar el componente ${item.nombre}?`))return;try{await eliminarComponente(item.id);success.value='Componente eliminado correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.',number=(v:number)=>new Intl.NumberFormat('es-PE',{maximumFractionDigits:2}).format(v)
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Sistemas y componentes / Componentes</nav><header class="hero"><div class="mark">CO</div><div><small>DANA · INFRAESTRUCTURA</small><h1>Componentes operacionales</h1><p>Registra infraestructura, ubicación y condiciones técnicas.</p></div><button @click="open()">+ Nuevo componente</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="tools"><input v-model.trim="query" placeholder="Nombre del componente" @keyup.enter="load(1)"><select v-model="systemFilter" @change="load(1)"><option value="">Todos los sistemas</option><option v-for="item in systems" :key="item.id" :value="item.id">{{item.distrito}} · {{item.nombre}}</option></select><button @click="load(1)">Buscar</button><span>{{total}} componentes</span></section><div v-if="loading" class="empty">Cargando componentes…</div><div v-else-if="!records.length" class="empty">No se encontraron componentes.</div><section v-else class="cards"><article v-for="item in records" :key="item.id"><header><div class="icon">⌬</div><div><small>{{item.tipo_nombre}}</small><h2>{{item.nombre}}</h2></div><span>{{item.condicion_nombre}}</span></header><p>{{item.observacion}}</p><div class="systems"><b v-for="system in item.sistemas" :key="system.id">{{system.nombre}}</b></div><div class="specs"><span><small>CAUDAL</small><b>{{number(item.caudal)}} L/s</b></span><span><small>CAPACIDAD</small><b>{{number(item.capacidad_nominal)}}</b></span><span><small>VOLUMEN</small><b>{{number(item.volumen)}}</b></span><span><small>COORDENADAS</small><b>{{item.puntos.length}} punto(s)</b></span></div><footer><button class="detail">Ver detalle</button><button class="edit" @click="open(item)">Modificar</button><button class="delete" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'ACTUALIZAR COMPONENTE':'NUEVA INFRAESTRUCTURA'}}</small><h2>{{editing?'Modificar componente':'Registrar componente'}}</h2></div><button type="button" @click="modal=false">×</button></header><h3>Información básica</h3><div class="fields"><label>Tipo de componente *<select v-model="form.tipo_componente_id" @change="resetPoints"><option v-for="item in types" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Nombre *<input v-model="form.nombre" maxlength="100"></label><label class="wide">Sistemas asociados *<select v-model="form.sistema_id" multiple size="4"><option v-for="item in systems" :key="item.id" :value="item.id">{{item.distrito}} · {{item.tipo}} · {{item.nombre}}</option></select></label><label class="wide">Observaciones *<textarea v-model="form.observacion" rows="2" maxlength="200"></textarea></label></div><h3>Georreferenciación · {{selectedType?.puntos||1}} punto(s)</h3><div class="points"><fieldset v-for="(point,index) in form.puntos" :key="index"><legend>Punto {{index+1}}</legend><input v-model.number="point.latitud" type="number" step="any" placeholder="Latitud"><input v-model.number="point.longitud" type="number" step="any" placeholder="Longitud"></fieldset></div><h3>Información técnica</h3><div class="fields"><label>Control de calidad *<select v-model="form.control_calidad"><option :value="false">No</option><option :value="true">Sí</option></select></label><label>Caudal (L/s) *<input v-model.number="form.caudal" type="number" min="0" step="0.01"></label><template v-if="form.control_calidad"><label>Variable SUNASS *<select v-model="form.variable_sunass"><option value="">Seleccione</option><option v-for="item in variables" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Código SUNASS *<input v-model="form.cod_sunass" maxlength="5"></label></template><label>Capacidad nominal *<input v-model.number="form.capacidad_nominal" type="number" min="0" step="0.01"></label><label>Volumen *<input v-model.number="form.volumen" type="number" min="0" step="0.01"></label><label>Fecha de instalación *<input v-model="form.fecha_instalacion" type="date"></label><label>Último mantenimiento *<input v-model="form.ultimo_mantenimiento" type="date"></label><label>Frecuencia (meses) *<input v-model.number="form.frecuencia_mant_meses" type="number" min="1"></label><label>Condición *<select v-model="form.condicion"><option v-for="(name,key) in conditions" :key="key" :value="key">{{name}}</option></select></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
