4px;flex-wrap:wrap}.systems b{padding:4px 6px;border-radius:8px;color:#526b8d;background:#eaf0f7;font-size:.42rem}.specs{margin-top:9px;display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.specs span{padding:7px;display:grid;border-radius:6px;background:#f5f7f8}.specs b{font-size:.48rem}.cards footer{margin-top:11px;display:flex;gap:5px}.cards footer button{padding:7px;border:0;border-radius:5px;font-size:.44rem}.detail{margin-right:auto;color:#fff;background:#536d91}.edit{color:#79500b;background:#ffe7bd}.delete{color:#a23d43;background:#fde8e8}.pager{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:10px;font-size:.52rem}.pager button:disabled{opacity:.45}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(780px,100%);max-height:94vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0 8px;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog h3{margin:12px 0 7px;padding-bottom:4px;border-bottom:1px solid #e5eaec;color:#65747b;font-size:.56rem;text-transform:uppercase}.fields{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.fields label{display:grid;gap:4px;font-size:.48rem}.fields .wide{grid-column:1/-1}.fields select[multiple]{height:72px}.points{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.points fieldset{padding:7px;display:grid;grid-template-columns:1fr 1fr;gap:6px;border:1px solid #e0e6e8;border-radius:6px}.points legend{font-size:.45rem}.dialog>footer{margin-top:15px;display:flex;justify-content:flex-end;gap:6px}.soft{color:#64727a!important;background:#edf1f3!important}@media(max-width:850px){.hero{flex-wrap:wrap}.hero>button{margin-left:0}.cards,.fields,.points{grid-template-columns:1fr}.fields .wide{grid-column:auto}.tools{align-items:stretch;flex-direction:column}.tools input,.tools select{width:100%;max-width:none}.tools span{margin:0}.specs{grid-template-columns:repeat(2,1fr)}}
</style>
